{
  "items": [
    {
      "title": "United Nations General Assembly Voting Data (1946–2026)",
      "url_or_doi": "https://digitallibrary.un.org/record/4060887?ln=en",
      "justification": "Official United Nations dataset containing recorded votes on General Assembly resolutions, including votes during the 2020s. Covers nearly all requested countries, including EU member states, the United Kingdom, Turkey, Western Balkan states, Moldova, and Georgia that are UN members. Particularly useful for studying foreign policy alignment, international cooperation, diplomatic disagreements, and voting behavior within international organizations. The October 2026 version includes resolutions through September 17, 2026. Kosovo is not represented as a separate UN member."
    },
    {
      "title": "Standard Eurobarometer 105 – Spring 2026",
      "url_or_doi": "https://data.europa.eu/data/datasets/s3613_105_2_std105_eng",
      "justification": "European Commission survey dataset measuring public attitudes toward the European Union, EU institutions, European integration, and international political developments. Provides comparable survey results for all 27 EU member states, with additional coverage of selected non-EU European countries. Particularly relevant for examining public trust in international organizations, perceptions of EU membership, and attitudes toward international crises in 2026."
    },
    {
      "title": "Varieties of Democracy (V-Dem) Dataset, Version 16 (2026)",
      "url_or_doi": "https://www.v-dem.net/data/",
      "justification": "Comprehensive country-year dataset covering democratic institutions, political accountability, civil society, electoral competition, political participation, and governance. Includes observations for the 2020s across the requested European countries. Useful for comparative research on institutional development, international democracy promotion, European integration, and political transformations. Particularly valuable for comparing EU member states with EU accession candidates."
    },
    {
      "title": "V-Dem Historical Dataset Archive",
      "url_or_doi": "https://www.v-dem.net/data/dataset-archive/",
      "justification": "Repository of historical V-Dem dataset releases, including datasets published during the 2020s. Enables researchers to compare political institutions and democratic developments across European countries using consistent country-year indicators. Useful for studying democratic backsliding, institutional reforms, political freedoms, and changes in governance associated with international integration."
    },
    {
      "title": "European Social Survey (ESS) – Round 10 and Round 11",
      "url_or_doi": "https://ess.sikt.no/en/data-builder/",
      "justification": "Cross-national survey microdata covering political trust, attitudes toward European institutions, trust in the United Nations, political participation, national identity, immigration, and democratic values. Includes observations collected during the 2020s from numerous requested European countries. Researchers can select participating countries, survey rounds, and variables to construct comparable datasets on perceptions of international politics and organizations. Country participation varies by round."
    },
    {
      "title": "World Values Survey – Wave 7 (2017–2022)",
      "url_or_doi": "https://doi.org/10.14281/18241.18",
      "justification": "International survey dataset examining political values, institutional confidence, national identity, democratic legitimacy, and attitudes toward international organizations. Includes observations from the early 2020s and covers a selection of the requested European countries. Particularly suitable for studying public confidence in the United Nations, European institutions, international cooperation, and democratic governance. Not all requested countries participated."
    },
    {
      "title": "World Values Survey – Longitudinal Dataset (1981–2022)",
      "url_or_doi": "https://doi.org/10.14281/18241.17",
      "justification": "Harmonized longitudinal survey dataset containing political and social attitudes across multiple survey waves, including observations from the early 2020s. Provides measures of political trust, confidence in international institutions, democratic attitudes, and national identity. Useful for examining whether attitudes toward international organizations changed between earlier decades and the 2020s in participating European countries."
    },
    {
      "title": "World Values Survey – Wave 7 Country-Level Data and Documentation",
      "url_or_doi": "https://www.worldvaluessurvey.org/WVSDocumentationWV7.jsp",
      "justification": "Official repository for country-specific survey files, questionnaires, and documentation from World Values Survey Wave 7. Researchers can identify participating European countries and extract variables related to political institutions, international organizations, national identity, geopolitical attitudes, and democratic legitimacy. Useful for constructing country comparisons covering the beginning of the 2020s."
    },
    {
      "title": "Harmonized Eurobarometer 2004–2021, Version 3.0.0",
      "url_or_doi": "https://cris.maastrichtuniversity.nl/en/datasets/harmonized-eurobarometer-2004-2021-300",
      "justification": "Harmonized survey dataset combining 35 Standard Eurobarometer surveys and more than 140 variables concerning EU policies, European identity, institutional trust, political attitudes, and European integration. Includes observations through 2021, making it relevant for studying the beginning of the 2020s. Particularly useful for comparing public opinion about European institutions across EU member states and examining changes associated with Brexit and European political developments."
    },
    {
      "title": "Eurostat – International Cooperation Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/international-cooperation/database",
      "justification": "Official European statistical database providing access to harmonized indicators for EU member states, enlargement countries, and European Neighbourhood Policy countries. Relevant geographical coverage includes the requested EU countries and several non-EU states, including Western Balkan countries, Turkey, Moldova, and Georgia. Useful for examining the economic, demographic, and institutional context of international cooperation and European integration during the 2020s. Specific dataset selection is required."
    },
    {
      "title": "Eurostat – Enlargement Countries Statistical Overview",
      "url_or_doi": "https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Enlargement_countries_-_statistical_overview",
      "justification": "Official Eurostat statistical collection covering Albania, Bosnia and Herzegovina, Georgia, Moldova, Montenegro, North Macedonia, Serbia, Turkey, and Kosovo. Provides comparative indicators relevant to EU enlargement, economic integration, and institutional development. Especially useful for analyzing the international political context of European Union accession during the 2020s. This is a statistical overview with links to underlying data rather than a single downloadable dataset."
    },
    {
      "title": "Eurostat – Enlargement and International Cooperation Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/international-cooperation/regional-cooperation/enlargement",
      "justification": "European Commission statistical resource focused on countries participating in the EU enlargement process. Covers Albania, Bosnia and Herzegovina, Georgia, Moldova, Montenegro, North Macedonia, Serbia, Turkey, and Kosovo. Useful for identifying comparable statistical datasets relevant to European integration, accession negotiations, and institutional convergence during the 2020s. Provides access to enlargement-related statistical resources rather than a single political dataset."
    },
    {
      "title": "UN General Assembly and Security Council Voting Data – UNIndex",
      "url_or_doi": "https://unindex.org/api-docs",
      "justification": "Structured access to United Nations General Assembly and Security Council voting records, with country, voting-position, and date filters. The underlying data includes voting records from the 2020s. Particularly useful for studying European countries' foreign policy positions, diplomatic coalitions, support for UN resolutions, and alignment on international security issues. The API supports country-specific extraction and comparative analysis."
    },
    {
      "title": "Correlates of War – Intergovernmental Organizations Dataset",
      "url_or_doi": "https://correlatesofwar.org/data-sets/IGOs/",
      "justification": "Historical dataset documenting state membership in intergovernmental organizations and shared organizational memberships between countries. Relevant for investigating the institutional foundations of international cooperation among European states. Includes many of the requested countries, but the available membership data ends in 2014. Therefore, it is best used as a historical baseline for analyzing organizational relationships entering the 2020s rather than as a source of current membership observations."
    },
    {
      "title": "Central Statistics Office Ireland – Trust Survey 2025: International Comparisons",
      "url_or_doi": "https://www-cloud.cso.ie/en/releasesandpublications/ep/p-trsic/trustsurvey2025internationalcomparisons/results/",
      "justification": "Official statistical publication containing internationally comparable survey results on public trust in institutions, including international organizations such as the United Nations. Includes data for participating countries in 2023 and 2025. Particularly relevant for comparing perceptions of international organizations in Ireland and other participating European countries. Geographic coverage is limited to surveyed countries rather than the complete requested list."
    },
    {
      "title": "Central Statistics Office Ireland – Trust in International Organisations (TRA312)",
      "url_or_doi": "https://data.cso.ie/table/TRA312",
      "justification": "Official statistical dataset containing internationally comparable measures of trust in international organizations. Relevant for studying institutional confidence and public perceptions of international governance during the 2020s. Allows researchers to compare Ireland with other participating countries and investigate variation in public confidence in organizations such as the United Nations."
    },
    {
      "title": "Eurostat – European Countries Comparative Statistical Dataset (tin00127)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/tin00127/CustomView_1/table?lang=en",
      "justification": "Official Eurostat dataset with observations extending through the 2020s and geographic coverage that includes EU member states, the United Kingdom, Turkey, Montenegro, North Macedonia, Albania, Serbia, Bosnia and Herzegovina, and Kosovo. Useful as a supplementary source of comparable national indicators for research on European integration and international cooperation. Its subject matter is not directly international politics, so it should be combined with political or institutional datasets."
    }
  ]
}
